#!/usr/bin/env python3
"""
KPR Tenant Sales — one-click deploy
Drop this file in the ROOT of your Replit project, then in Shell tab run:
    python3 deploy_tenant_sales.py
"""
import os, base64

BASE = os.path.dirname(os.path.abspath(__file__))

def patch(path, old, new, label):
    full = os.path.join(BASE, path)
    try:
        with open(full, encoding="utf-8") as f:
            content = f.read()
    except FileNotFoundError:
        print(f"  MISS {label} — file not found: {path}")
        return
    if old not in content:
        print(f"  SKIP {label} — already applied")
        return
    with open(full, "w", encoding="utf-8") as f:
        f.write(content.replace(old, new, 1))
    print(f"  OK   {label}")

def write_new(path, b64_content, label):
    full = os.path.join(BASE, path)
    os.makedirs(os.path.dirname(full), exist_ok=True)
    with open(full, "wb") as f:
        f.write(base64.b64decode(b64_content))
    print(f"  OK   {label}")

print("\n=== KPR Tenant Sales — applying changes ===\n")

